import{_ as n,l as E,o as a,c as i,v as t,p as l,x as r,d as s,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"REE 的存在与揭示","description":"","frontmatter":{"title":"REE 的存在与揭示","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ree-revelation.md","filePath":"econ/ree-revelation.md","lastUpdated":1789023840000}'),d={name:"econ/ree-revelation.md"};function c(m,e,h,_,R,B){const o=E("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="ree-的存在与揭示" tabindex="-1">REE 的存在与揭示 <a class="header-anchor" href="#ree-的存在与揭示" aria-label="Permalink to &quot;REE 的存在与揭示&quot;">​</a></h1><div class="epigraph"><p>完全揭示的理性预期均衡在状态空间足够丰富时可以普遍存在；噪声一进来，普遍的是部分揭示，完全揭示变成刀刃。</p><footer>—— 据 Radner, Econometrica 1979；Allen, Econometrica 1981；对照 Grossman–Stiglitz 的部分揭示</footer></div><p><a href="/econ/admati-multi-asset-ree">上一课</a>在正态线性里把价格向量写成 \\(A\\theta+Bz\\)。本课缺口是离开函数形式：REE 作为一种对应，何时存在、价格映射何时一对一。不重做矩阵求逆，不估计揭示度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Radner（1979）的「完全沟通均衡」：现货价格作为信号，若不同的基本面状态给出不同的价格，看见 \\(p\\) 就等于看见状态，未持有私人信号的人也知情。在平滑偏好与紧致状态空间上，完全揭示的 REE <strong>普遍</strong>存在——因为把价格映射微扰一下就能分开状态，而需求在完全信息下已经定义好。这与 GS 不打架：Radner 的世界里信息是禀赋，没有采集成本 \\(c\\)，也没有故意加入的 \\(z\\)。</p><p>Allen（1981）等指出：一旦允许价格不分开状态（部分揭示），存在性立刻变难。信念依赖 \\(p\\)，需求作为 \\(p\\) 的函数可能不连续——状态被价格聚成原子时，条件期望会跳。线性正态靠联合连续分布躲过跳跃；一般模型需要额外结构（噪声、凸性、或只找近似均衡）。</p><p>缺口是把「存在」与「揭示」拆开：有均衡不等于完全揭示；完全揭示在无噪声、无成本时普遍，在有 \\(c\\) 或有 \\(z\\) 时不是均衡或不是普遍。</p><p><span class="marginnote">Jordan、Radner 以及后续的「普遍完全揭示」文献，对象是抽象状态空间上的价格函数，不是某一组美股的 \\(R^2\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把 REE 写成不动点：猜测一个从状态（含信号、噪声）到价格的映射 \\(\\phi\\)，诱导出每人的条件信念，再要求在这些信念下的超额需求在 \\(\\phi(\\omega)\\) 处为零。完全揭示：\\(\\phi\\) 在基本面上可逆（差一个与偏好无关的标签）。部分揭示：\\(\\phi\\) 把不同基本面打到同一 \\(p\\)，条件信念是那个原子上的后验。</p><p>GS / Hellwig / Admati 是部分揭示的参数化构造。Radner 是完全揭示的普遍性定理。两者的前提不同：有没有残差不确定性、有没有采集成本。本课禁止用其中一篇否证另一篇。</p>',11)),(a(),l(A,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAD%5B%22%E6%97%A0%E5%99%AA%E5%A3%B0%E3%80%81%E4%BF%A1%E6%81%AF%E5%A4%96%E7%94%9F%22%5D%20--%3E%20FULL%5B%22%E5%AE%8C%E5%85%A8%E6%8F%AD%E7%A4%BA%E6%99%AE%E9%81%8D%E5%AD%98%E5%9C%A8%22%5D%0A%20%20GS%5B%22%E6%9C%89%20c%20%E6%88%96%E6%9C%89%20z%22%5D%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E6%8F%AD%E7%A4%BA%E6%89%8D%E6%98%AF%E5%9D%87%E8%A1%A1%22%5D%0A%20%20PART%20--%3E%20EX%5B%22%E5%AD%98%E5%9C%A8%E9%9D%A0%E6%AD%A3%E5%88%99%3A%20%E6%AD%A3%E6%80%81%E6%88%96%E5%B9%B3%E6%BB%91%E5%99%AA%E5%A3%B0%22%5D%0A%20%20FULL%20--%3E%20COST%5B%22%E4%B8%80%E5%8A%A0%E9%87%87%E9%9B%86%E6%88%90%E6%9C%AC%E5%8D%B3%E5%B4%A9%E6%BA%83%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p><a href="/econ/state-prices">状态价格</a>在完全信息、完全市场上给出唯一 \\(q\\)。REE 讨论的是 \\(q\\) 或 \\(p\\) <strong>作为信号</strong>还携带多少别人不知道的东西。两套对象：一套是或有商品的竞争价格，一套是信息加总。完全揭示的 REE 把第二套压进第一套；部分揭示让第二套永远残缺。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>完全揭示的机制是分离：若两个状态还并在同一价格上，而两人在这两个状态里的需求不同，那么把价格稍微标出差异，超额需求会把映射推开——普遍性来自这种可分离。部分揭示的机制是混淆必要：要么有人必须被补偿才生产信息，要么总量噪声与基本面绑死。存在性的机制是需求对信念连续：噪声把原子摊成密度，线性正态是最省事的摊法。</p><p>战略操纵（有限人影响 \\(p\\)）会破坏价格接受，存在性要换成博弈的贝叶斯纳什，后课 Kyle 对照。本课仍停在竞争。</p><p><span class="marginnote">「几乎完全揭示」：噪声方差趋于零时，价格收敛到完全信息价格，但任意小噪声下采集激励仍可保留。GS 的极限与 Radner 的普遍性在极限点相遇，在任何正噪声处分开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「普遍存在」读成「现实价格完全揭示」。普遍性是在无噪声模型的拓扑意义上。也不要把不存在定理写成市场崩盘：那是某个函数空间里找不到不动点，不是交易停止。本课不讨论限价簿上因离散档位导致的「价格不能分开状态」——档位是协议，见量化栏。</p><p>下一课让信号重新变成选择：采集的策略替代与策略互补。存在与揭示假定信号已在手里；获取把 \\(\\lambda\\) 或精度变成均衡对象。</p><p>后课默认：无噪声时完全揭示普遍；有成本或有噪声时工作均衡是部分揭示；线性正态是构造，不是定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Radner：信息外生、无噪声时，完全揭示 REE 普遍存在。</li><li>有 \\(c\\) 或 \\(z\\) 时，完全揭示不是工作均衡；部分揭示的存在需要正则。</li><li>价格作为信号，与状态价格作为或有商品，是两套对象。</li><li>出处：Radner, <em>Econometrica</em> 1979；Allen, <em>Econometrica</em> 1981；对照 Grossman–Stiglitz 1980。</li></ul>',11))])}const f=n(d,[["render",c]]);export{D as __pageData,f as default};
